#include <fstream>
#include <iostream>
#include <string>
#include <thread>

// True when line begins with key, the way each field of /proc/cpuinfo starts.
bool starts_with(const std::string& line, const std::string& key) {
    return line.compare(0, key.size(), key) == 0;
}

int main() {
    std::ifstream cpuinfo("/proc/cpuinfo");  // one block of "key : value" lines per logical CPU
    std::string line, model;
    int logical = 0, siblings = 0, cores = 0;
    while (std::getline(cpuinfo, line)) {
        if (starts_with(line, "processor")) {
            ++logical;
        } else if (starts_with(line, "model name")) {
            model = line.substr(line.find(':') + 2);
        } else if (starts_with(line, "siblings")) {  // logical CPUs per socket
            siblings = std::stoi(line.substr(line.find(':') + 1));
        } else if (starts_with(line, "cpu cores")) {  // cores per socket
            cores = std::stoi(line.substr(line.find(':') + 1));
        }
    }
    const int per_core = cores > 0 ? siblings / cores : 1;  // no "cpu cores" line: count 1
    // The numbers differ on every machine. Uncomment to see this one's:
    // std::cout << model << ", " << logical << " logical CPUs, " << per_core << " per core\n";
    std::cout << "logical CPUs at least 1: " << (logical >= 1 ? "yes" : "no") << '\n';
    std::cout << "threads per core 1 or 2: " << (per_core == 1 || per_core == 2 ? "yes" : "no") << '\n';
    const bool agrees = std::thread::hardware_concurrency() == static_cast<unsigned>(logical);
    std::cout << "hardware_concurrency agrees: " << (agrees ? "yes" : "no") << '\n';
    return 0;
}

