// -O2
#include <algorithm>
#include <cstdint>
#include <ctime>
#include <iostream>
#include <sched.h>
#include <thread>
#include <vector>

// CPU-bound work: random walks of 100 one-tick steps, each path seeded by its number,
// so the total is the same however the paths are split.
int64_t walk_paths(int begin, int end) {
    int64_t total = 0;
    for (int p = begin; p < end; ++p) {
        uint64_t x = p;
        int64_t price = 10000;
        for (int step = 0; step < 100; ++step) {
            x = x * 6364136223846793005ULL + 1442695040888963407ULL;
            price += (x >> 63) ? 1 : -1;
        }
        total += price;
    }
    return total;
}

// Splits the paths over k threads. Each writes only its own slot.
int64_t run_threads(int k, int paths) {
    std::vector<int64_t> partial(k);
    std::vector<std::thread> threads;
    for (int i = 0; i < k; ++i) {
        threads.emplace_back([&partial, i, k, paths] {
            partial[i] = walk_paths(int64_t(paths) * i / k, int64_t(paths) * (i + 1) / k);
        });
    }
    for (std::thread& t : threads) {
        t.join();  // wait for every thread before reading the slots
    }
    int64_t total = 0;
    for (int64_t x : partial) {
        total += x;
    }
    return total;
}

int main() {
    const int cpus = std::max(1u, std::thread::hardware_concurrency());  // 0 means "can't tell"
    timespec slice{};
    sched_rr_get_interval(0, &slice);  // how long this thread may run before it can be preempted
    // Both change from machine to machine. Uncomment to see this one's:
    // std::cout << cpus << " logical CPUs, a " << slice.tv_nsec / 1'000'000 << " ms slice\n";
    std::cout << "1 thread:    " << run_threads(1, 3'000'000) << '\n';
    std::cout << "one per CPU: " << run_threads(cpus, 3'000'000) << '\n';
    std::cout << "two per CPU: " << run_threads(2 * cpus, 3'000'000) << '\n';
    return 0;
}

