// -O2
#include <cstdint>
#include <iostream>
#include <sys/resource.h>
#include <thread>
#include <unistd.h>

int main() {
    int to_echo[2], to_main[2];  // each pipe: [0] is its read end, [1] its write end
    if (pipe(to_echo) != 0 || pipe(to_main) != 0) {
        return 1;
    }
    const int64_t trips = 10'000;

    std::thread echo([&] {  // sends every number straight back
        for (int64_t i = 0; i < trips; ++i) {
            int64_t x = 0;
            read(to_echo[0], &x, sizeof x);  // sleeps in the kernel until main writes
            write(to_main[1], &x, sizeof x);
        }
    });

    rusage before{}, after{};
    getrusage(RUSAGE_THREAD, &before);  // this thread's counters so far (Linux only)
    int64_t sum = 0;
    for (int64_t i = 1; i <= trips; ++i) {
        write(to_echo[1], &i, sizeof i);
        int64_t back = 0;
        read(to_main[0], &back, sizeof back);  // sleeps until echo answers
        sum += back;
    }
    getrusage(RUSAGE_THREAD, &after);
    echo.join();
    // std::cout << "voluntary: " << after.ru_nvcsw - before.ru_nvcsw
    //           << ", involuntary: " << after.ru_nivcsw - before.ru_nivcsw << '\n';

    std::cout << "round trips: " << trips << '\n';
    std::cout << "sum: " << sum << '\n';
    return 0;
}

