// -O2
#include <cstdint>
#include <iostream>
#include <thread>
#include <unistd.h>

int main() {
    int64_t orders = 0, limit = 0;
    std::cin >> orders >> limit;
    int to_check[2], to_main[2];
    if (pipe(to_check) != 0 || pipe(to_main) != 0) {
        return 1;
    }

    std::thread checker([&] {  // answers each size with the size itself, or 0 if it's over the limit
        for (int64_t i = 0; i < orders; ++i) {
            int64_t size = 0;
            read(to_check[0], &size, sizeof size);
            int64_t verdict = size <= limit ? size : 0;
            write(to_main[1], &verdict, sizeof verdict);
        }
    });

    int64_t accepted = 0, accepted_size = 0;
    for (int64_t i = 0; i < orders; ++i) {
        int64_t size = i * 37 % 500 + 1;  // order sizes from 1 to 500 lots
        write(to_check[1], &size, sizeof size);
        int64_t verdict = 0;
        read(to_main[0], &verdict, sizeof verdict);
        if (verdict > 0) {
            ++accepted;
            accepted_size += verdict;
        }
    }
    checker.join();
    std::cout << "orders: " << orders << '\n';
    std::cout << "accepted: " << accepted << '\n';
    std::cout << "accepted size: " << accepted_size << '\n';
    return 0;
}

