#include <cstring>
#include <iostream>
#include <pthread.h>
#include <sched.h>
#include <sys/resource.h>

int main() {
    const int start = getpriority(PRIO_PROCESS, 0);  // 0 unless something lowered it
    setpriority(PRIO_PROCESS, 0, start + 10);        // a batch job steps aside: always allowed
    const int lowered = getpriority(PRIO_PROCESS, 0);
    std::cout << "nice went up: " << (lowered > start ? "yes" : "no") << '\n';
    // Going back, setpriority(PRIO_PROCESS, 0, start), takes privilege.

    std::cout << "SCHED_FIFO priorities: " << sched_get_priority_min(SCHED_FIFO) << " to "
              << sched_get_priority_max(SCHED_FIFO) << '\n';
    sched_param param{};
    param.sched_priority = 100;  // past the top of the range
    int err = pthread_setschedparam(pthread_self(), SCHED_FIFO, &param);  // real-time, for this thread
    std::cout << "SCHED_FIFO at 100: " << (err == 0 ? "done" : std::strerror(err)) << '\n';
    return 0;
}

